from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_handles_empty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 1, False), event("c", 1, None), event("d", 1, False)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (8, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_transcript_log_values_whitespace_and_skipped_lines():
    lines = ["  \n", "  # comment, not a record", " a ,  3 , 1 ",
             "b, -2, 0", "c, 0,   "]
    assert parse_transcript_log(lines) == [event("a", 3, True), event("b", -2, False),
                                           event("c", 0, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,0,extra", "a,not-a-day,1", "a,1,true"])
def test_parse_transcript_log_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "ok,1,1", line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    first = event("a", 5, True)
    last = event("a", 1, None)
    events = [first, event("z", 1, True), event("b", 0, False), last,
              event("c", 1, False)]
    assert dedupe_transcripts(events) == [events[2], last, events[4], events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_include_empty_days_and_filter_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, False), event("c", 4, None)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_skips_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "b": [event("b", 1, False)],
              "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_orders_keys():
    result = flag_rate_by_group({"z": [], "b": [event("b", 1, None)],
                                 "a": [event("a", 1, True)]})
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_and_ignores_negative_counts():
    assert longest_flag_streak([1, 2, 0, 1, -1, 2, 3, 4]) == 3
    assert longest_flag_streak([-1, 0]) == 0
    assert longest_flag_streak([]) == 0
